#!/usr/bin/env python3
"""
Script combinado:
1. Anade la opcion de pedir factura con datos fiscales (razon social,
   CIF/NIF, direccion fiscal) en el checkout - opcional, con una casilla.
2. Elimina del checkout los campos de tarjeta (numero/caducidad/CVC) y los
   botones de metodo de pago (Apple/Google/PayPal/Revolut/Klarna) que NO
   se usaban realmente - el pago de verdad siempre ha ocurrido en la
   pagina seguridad de Stripe, a la que se redirige despues. Tambien
   quitaba el aviso "Pago de demostracion, no se cobra ninguna tarjeta"
   que quedo de la plantilla original y ya no era cierto.
3. Habilita que Stripe muestre automaticamente los metodos de pago reales
   que tengas activados en tu panel de Stripe (tarjeta, Apple Pay, Google
   Pay, Bizum...), en vez de forzar solo "tarjeta" como hasta ahora.
4. Muestra los datos de factura en el panel de administracion (aviso en
   la lista, detalle del pedido, y columnas nuevas en el CSV exportado).

IMPORTANTE sobre Apple Pay / Google Pay / Bizum: el codigo ya no limita
los metodos de pago, pero para que aparezcan de verdad tienes que
activarlos en Stripe -> Configuracion -> Metodos de pago
(https://dashboard.stripe.com/settings/payment_methods):
  - Tarjeta: activada por defecto.
  - Apple Pay: activada por defecto.
  - Google Pay: normalmente DESACTIVADA por defecto, hay que activarla.
  - Bizum: puede requerir activacion/verificacion especifica de Stripe
    para cuentas en España. Si no aparece la opcion, es posible que
    tengas que solicitarlo a Stripe o esperar a que estar disponible
    para tu cuenta.

Uso: colocar este archivo en la raiz del repo (fresh-start-app) y ejecutar:
    python3 fix_facturacion_y_metodos_pago.py

Despues hay que aplicar la migracion a Supabase y volver a desplegar la
funcion (instrucciones al final).
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def write_new_file(relpath, content):
    path = ROOT / relpath
    if path.exists():
        print(f"AVISO: {relpath} ya existe, no se sobrescribe (¿ya estaba aplicado?)")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print(f"OK: creado {relpath}")


def overwrite_file(relpath, content, marker):
    """Sobrescribe el archivo completo, pero solo si no contiene ya el marcador
    (para no pisar el archivo si el script ya se ejecuto antes)."""
    path = ROOT / relpath
    if not path.exists():
        print(f"ERROR: no encuentro {relpath} en {ROOT}")
        sys.exit(1)
    current = path.read_text(encoding="utf-8")
    if marker in current:
        print(f"AVISO: {relpath} ya parece tener este cambio aplicado, no se toca")
        return
    path.write_text(content, encoding="utf-8")
    print(f"OK: reescrito {relpath}")


def edit_file(relpath, replacements):
    path = ROOT / relpath
    if not path.exists():
        print(f"ERROR: no encuentro {relpath} en {ROOT}")
        sys.exit(1)
    text = path.read_text(encoding="utf-8")
    original = text
    for old, new, desc in replacements:
        count = text.count(old)
        if count == 0:
            print(f"AVISO: no encontrado en {relpath} -> {desc} (¿ya estaba aplicado?)")
            continue
        text = text.replace(old, new)
        print(f"OK: aplicado en {relpath} -> {desc}")
    if text != original:
        path.write_text(text, encoding="utf-8")
    else:
        print(f"(sin cambios en {relpath})")


# --- 1. Migracion SQL ------------------------------------------------------
SQL_MIGRATION = "-- Datos de facturacion opcionales (razon social, CIF/NIF, direccion fiscal),\n-- solo rellenos cuando el cliente marca en el checkout que necesita\n-- factura con sus datos fiscales. Null cuando no los pide.\nalter table public.orders add column if not exists invoice_data jsonb;\n"
write_new_file("supabase/migrations/20260813000000_add_invoice_data_to_orders.sql", SQL_MIGRATION)

# --- 2. checkout.tsx completo (factura + limpieza de pago) -----------------
CHECKOUT_TSX = "import { createFileRoute, Link, useNavigate } from \"@tanstack/react-router\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { ArrowLeft, Lock, ShieldCheck, Truck, FileText } from \"lucide-react\";\nimport { toast } from \"sonner\";\nimport { useCart } from \"@/lib/cart-store\";\nimport { useAuth } from \"@/lib/auth-context\";\nimport { useI18n } from \"@/lib/i18n\";\nimport { supabase } from \"@/integrations/supabase/client\";\n\n\nexport const Route = createFileRoute(\"/checkout\")({\n  head: () => ({\n    meta: [\n      { title: \"Checkout \u2014 Xprint Wear\" },\n      { name: \"description\", content: \"Secure checkout for your Xprint Wear custom pieces.\" },\n      { property: \"og:title\", content: \"Checkout \u2014 Xprint Wear\" },\n      { property: \"og:description\", content: \"Secure checkout for your Xprint Wear custom pieces.\" },\n      { property: \"og:type\", content: \"website\" },\n      { name: \"twitter:card\", content: \"summary_large_image\" },\n      { name: \"robots\", content: \"noindex\" },\n    ],\n  }),\n  component: CheckoutPage,\n});\n\nfunction CheckoutPage() {\n  const { t } = useI18n();\n  const { items, total, unitPrice } = useCart();\n  const { user } = useAuth();\n  const navigate = useNavigate();\n  const [busy, setBusy] = useState(false);\n  const [wantsInvoice, setWantsInvoice] = useState(false);\n\n  const shipping = total > 120 ? 0 : total > 0 ? 9 : 0;\n  const tax = Math.round(total * 0.08 * 100) / 100;\n  const grand = total + shipping + tax;\n\n  const onSubmit = async (e: React.FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    if (!items.length || busy) return;\n    setBusy(true);\n\n    const form = new FormData(e.currentTarget);\n    const customerEmail = String(form.get(\"email\") || \"\").trim();\n    const customerPhone = String(form.get(\"phone\") || \"\").trim();\n    const customerName = String(form.get(\"name\") || \"\").trim();\n    const shippingAddress = {\n      address: String(form.get(\"address\") || \"\").trim(),\n      city: String(form.get(\"city\") || \"\").trim(),\n      postal: String(form.get(\"postal\") || \"\").trim(),\n      country: String(form.get(\"country\") || \"\").trim(),\n    };\n    const invoiceData = wantsInvoice\n      ? {\n          companyName: String(form.get(\"invoiceCompany\") || \"\").trim(),\n          taxId: String(form.get(\"invoiceTaxId\") || \"\").trim(),\n          address: String(form.get(\"invoiceAddress\") || \"\").trim(),\n        }\n      : null;\n\n    try {\n      const { data, error } = await supabase.functions.invoke(\"create-checkout-session\", {\n        body: {\n          items,\n          subtotal: total,\n          shipping,\n          tax,\n          total: grand,\n          customerEmail: customerEmail || user?.email || null,\n          customerName,\n          customerPhone,\n          shippingAddress,\n          invoiceData,\n          origin: window.location.origin,\n        },\n      });\n\n      if (error) throw error;\n      if (!data?.url) throw new Error(\"No se ha recibido la URL de pago\");\n\n      window.location.href = data.url;\n    } catch (err) {\n      setBusy(false);\n      toast.error(err instanceof Error ? err.message : \"No se pudo iniciar el pago\");\n    }\n  };\n\n\n  if (!items.length) {\n    return (\n      <main className=\"mx-auto max-w-3xl px-6 py-24 text-center\">\n        <p className=\"font-display text-3xl uppercase\">{t(\"checkout_title\")}</p>\n        <p className=\"mt-4 text-muted-foreground\">{t(\"empty_checkout\")}</p>\n        <Link\n          to=\"/shop\"\n          className=\"mt-8 inline-block rounded-full border border-foreground px-6 py-3 text-sm font-semibold uppercase tracking-widest transition hover:bg-foreground hover:text-background\"\n        >\n          {t(\"continue_shopping\")}\n        </Link>\n      </main>\n    );\n  }\n\n  return (\n    <main className=\"relative\">\n      {/* Ambient background */}\n      <div className=\"pointer-events-none absolute inset-0 -z-10 overflow-hidden\">\n        <div className=\"absolute -left-40 top-0 h-[500px] w-[500px] rounded-full bg-[hsl(280_100%_60%/0.12)] blur-3xl\" />\n        <div className=\"absolute right-0 top-96 h-[400px] w-[400px] rounded-full bg-[hsl(320_100%_60%/0.10)] blur-3xl\" />\n      </div>\n\n      <div className=\"mx-auto max-w-6xl px-4 pb-24 pt-8 sm:px-6\">\n        <button\n          onClick={() => navigate({ to: \"/shop\" })}\n          className=\"mb-6 inline-flex items-center gap-1.5 text-xs font-semibold uppercase tracking-widest text-muted-foreground transition hover:text-foreground\"\n        >\n          <ArrowLeft className=\"h-3.5 w-3.5\" /> {t(\"back_to_shop\")}\n        </button>\n\n        <div className=\"mb-10\">\n          <p className=\"text-xs uppercase tracking-[0.3em] text-muted-foreground\">Xprint Wear</p>\n          <h1 className=\"mt-2 font-display text-4xl uppercase leading-none tracking-tight sm:text-5xl\">\n            {t(\"checkout_title\")} <span className=\"text-holo\">.</span>\n          </h1>\n          <p className=\"mt-3 max-w-md text-sm text-muted-foreground\">{t(\"checkout_sub\")}</p>\n        </div>\n\n        <form onSubmit={onSubmit} className=\"grid gap-8 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]\">\n          {/* Left: form */}\n          <div className=\"space-y-8\">\n            <Section title={t(\"contact_info\")}>\n              <Field label={t(\"email\")} name=\"email\" type=\"email\" required placeholder=\"tucorreo@ejemplo.com\" />\n              <Field label={t(\"phone\")} name=\"phone\" type=\"tel\" placeholder=\"+34 600 000 000\" />\n            </Section>\n\n            <Section title={t(\"shipping_address\")} icon={<Truck className=\"h-4 w-4\" />}>\n              <Field label={t(\"full_name\")} name=\"name\" required placeholder=\"Alex Rivera\" />\n              <Field label={t(\"address_line\")} name=\"address\" required placeholder=\"Calle Gran V\u00eda 42\" />\n              <div className=\"grid grid-cols-2 gap-3\">\n                <Field label={t(\"city\")} name=\"city\" required placeholder=\"Madrid\" />\n                <Field label={t(\"postal_code\")} name=\"postal\" required placeholder=\"28013\" />\n              </div>\n              <Field label={t(\"country\")} name=\"country\" required placeholder=\"Espa\u00f1a\" />\n            </Section>\n\n            <Section title=\"Facturaci\u00f3n\" icon={<FileText className=\"h-4 w-4\" />}>\n              <label className=\"flex cursor-pointer items-center gap-2 text-sm\">\n                <input\n                  type=\"checkbox\"\n                  checked={wantsInvoice}\n                  onChange={(e) => setWantsInvoice(e.target.checked)}\n                  className=\"h-4 w-4 rounded border-border accent-foreground\"\n                />\n                Necesito factura con mis datos fiscales\n              </label>\n              {wantsInvoice && (\n                <div className=\"space-y-3 pt-1\">\n                  <Field label=\"Raz\u00f3n social / Nombre fiscal\" name=\"invoiceCompany\" required placeholder=\"Mi Empresa S.L.\" />\n                  <Field label=\"CIF / NIF\" name=\"invoiceTaxId\" required placeholder=\"B12345678\" />\n                  <Field\n                    label=\"Direcci\u00f3n fiscal (si es distinta a la de env\u00edo)\"\n                    name=\"invoiceAddress\"\n                    placeholder=\"Calle Ejemplo 1, 28001 Madrid\"\n                  />\n                </div>\n              )}\n            </Section>\n\n            <Section title={t(\"payment\")} icon={<Lock className=\"h-4 w-4\" />}>\n              <div className=\"rounded-xl border border-border bg-muted/30 p-5 text-center\">\n                <div className=\"mx-auto mb-2 flex h-10 w-10 items-center justify-center rounded-full bg-foreground text-background\">\n                  <Lock className=\"h-4 w-4\" />\n                </div>\n                <p className=\"font-display text-sm uppercase tracking-wider\">Pago 100% seguro con Stripe</p>\n                <p className=\"mt-1 text-[11px] text-muted-foreground\">\n                  En el siguiente paso podr\u00e1s elegir c\u00f3mo pagar (tarjeta, Apple Pay, Google Pay, Bizum u otros m\u00e9todos\n                  disponibles) en la pasarela segura de Stripe.\n                </p>\n              </div>\n              <p className=\"flex items-center gap-1.5 text-[11px] text-muted-foreground\">\n                <ShieldCheck className=\"h-3 w-3\" /> Tus datos de pago nunca pasan por nuestros servidores.\n              </p>\n            </Section>\n          </div>\n\n          {/* Right: summary */}\n          <aside className=\"lg:sticky lg:top-24 lg:self-start\">\n            <motion.div\n              initial={{ opacity: 0, y: 8 }}\n              animate={{ opacity: 1, y: 0 }}\n              className=\"overflow-hidden rounded-2xl border border-border bg-card shadow-sm\"\n            >\n              <div className=\"border-b border-border bg-muted/40 px-5 py-4\">\n                <p className=\"font-display text-lg uppercase tracking-tight\">{t(\"order_summary\")}</p>\n              </div>\n\n              <ul className=\"max-h-80 divide-y divide-border overflow-y-auto\">\n                {items.map((i) => (\n                  <li key={i.id} className=\"flex gap-3 px-5 py-4\">\n                    <div\n                      className=\"relative h-16 w-16 shrink-0 overflow-hidden rounded-md border border-border\"\n                      style={{ backgroundColor: \"#ffffff\" }}\n                    >\n                      {i.image && (\n                        <img src={i.image} alt={i.name} className=\"h-full w-full object-contain mix-blend-multiply\" />\n                      )}\n                      <span className=\"absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-foreground px-1 text-[10px] font-bold text-background\">\n                        {i.qty}\n                      </span>\n                    </div>\n                    <div className=\"min-w-0 flex-1\">\n                      <p className=\"truncate font-display text-sm uppercase leading-tight\">{i.name}</p>\n                      <p className=\"mt-0.5 text-[11px] text-muted-foreground\">\n                        {i.size} \u00b7 {i.colorName}\n                      </p>\n                      {i.elements.filter((el) => el.kind === \"text\" && el.text).map((el) => (\n                        <p key={el.id} className=\"text-[11px] text-muted-foreground\">\"{el.text}\"</p>\n                      ))}\n                    </div>\n                    <p className=\"whitespace-nowrap text-sm font-semibold\">\n                      \u20ac{(unitPrice(i) * i.qty).toFixed(2)}\n                    </p>\n                  </li>\n                ))}\n              </ul>\n\n              <div className=\"space-y-2 border-t border-border px-5 py-4 text-sm\">\n                <Row label={t(\"subtotal\")} value={`\u20ac${total.toFixed(2)}`} />\n                <Row label={t(\"shipping\")} value={shipping === 0 ? t(\"free\") : `\u20ac${shipping.toFixed(2)}`} />\n                <Row label={t(\"tax\")} value={`\u20ac${tax.toFixed(2)}`} />\n                <div className=\"mt-3 flex items-center justify-between border-t border-border pt-3 font-display text-lg uppercase\">\n                  <span>{t(\"total\")}</span>\n                  <span>\u20ac{grand.toFixed(2)}</span>\n                </div>\n              </div>\n\n              <div className=\"border-t border-border p-5\">\n                <button\n                  type=\"submit\"\n                  disabled={busy}\n                  className=\"holo-gradient relative w-full overflow-hidden rounded-full py-4 font-display text-sm uppercase tracking-[0.2em] text-white shadow-lg transition active:scale-[0.98] disabled:opacity-70\"\n                >\n                  {busy ? t(\"processing\") : t(\"place_order\")}\n                </button>\n                <p className=\"mt-3 flex items-center justify-center gap-1.5 text-[11px] text-muted-foreground\">\n                  <Lock className=\"h-3 w-3\" /> Secure \u00b7 encrypted \u00b7 Xprint Wear\n                </p>\n              </div>\n            </motion.div>\n          </aside>\n        </form>\n      </div>\n    </main>\n  );\n}\n\nfunction Section({\n  title,\n  icon,\n  children,\n}: {\n  title: string;\n  icon?: React.ReactNode;\n  children: React.ReactNode;\n}) {\n  return (\n    <section className=\"rounded-2xl border border-border bg-card p-5 shadow-sm\">\n      <p className=\"mb-4 flex items-center gap-2 font-display text-sm uppercase tracking-widest\">\n        {icon}\n        {title}\n      </p>\n      <div className=\"space-y-3\">{children}</div>\n    </section>\n  );\n}\n\nfunction Field({\n  label,\n  ...rest\n}: React.InputHTMLAttributes<HTMLInputElement> & { label: string }) {\n  return (\n    <label className=\"block\">\n      <span className=\"mb-1 block text-[11px] uppercase tracking-widest text-muted-foreground\">{label}</span>\n      <input\n        {...rest}\n        className=\"w-full rounded-lg border border-border bg-background px-3.5 py-2.5 text-sm outline-none transition placeholder:text-muted-foreground/60 focus:border-foreground\"\n      />\n    </label>\n  );\n}\n\nfunction Row({ label, value }: { label: string; value: string }) {\n  return (\n    <div className=\"flex items-center justify-between text-muted-foreground\">\n      <span>{label}</span>\n      <span className=\"font-medium text-foreground\">{value}</span>\n    </div>\n  );\n}\n"
overwrite_file("src/routes/checkout.tsx", CHECKOUT_TSX, marker="Necesito factura con mis datos fiscales")

# --- 3. Edge Function: guardar invoice_data + no forzar solo tarjeta -------
EDGE_FUNCTION = "// Edge Function: create-checkout-session\n// Recibe los datos del pedido desde el checkout de la web, crea una fila\n// \"pending\" en la tabla orders, y abre una sesion de pago real en Stripe.\n// La clave secreta de Stripe vive solo aqui (variable de entorno del\n// servidor), nunca en el codigo del navegador.\n\nimport { createClient } from \"npm:@supabase/supabase-js@2\";\nimport Stripe from \"npm:stripe@17\";\n\nconst corsHeaders = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\n};\n\nDeno.serve(async (req) => {\n  if (req.method === \"OPTIONS\") {\n    return new Response(null, { headers: corsHeaders });\n  }\n\n  try {\n    const STRIPE_SECRET_KEY = Deno.env.get(\"STRIPE_SECRET_KEY\");\n    const SUPABASE_URL = Deno.env.get(\"SUPABASE_URL\");\n    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\");\n\n    if (!STRIPE_SECRET_KEY || !SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {\n      throw new Error(\"Faltan variables de entorno del servidor\");\n    }\n\n    const stripe = new Stripe(STRIPE_SECRET_KEY, { apiVersion: \"2024-11-20.acacia\" });\n    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);\n\n    const body = await req.json();\n    const {\n      items, subtotal, shipping, tax, total,\n      customerEmail, customerName, customerPhone,\n      shippingAddress, invoiceData, origin,\n    } = body;\n\n    if (!items?.length || !total || !origin) {\n      return new Response(JSON.stringify({ error: \"Datos de pedido incompletos\" }), {\n        status: 400, headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\n      });\n    }\n\n    const orderNumber = \"XPW-\" + Math.random().toString(36).slice(2, 8).toUpperCase();\n\n    const { error: insertError } = await supabase.from(\"orders\").insert({\n      order_number: orderNumber,\n      status: \"pending\",\n      customer_email: customerEmail ?? null,\n      customer_name: customerName ?? null,\n      customer_phone: customerPhone ?? null,\n      shipping_address: shippingAddress ?? null,\n      invoice_data: invoiceData ?? null,\n      items,\n      subtotal, shipping, tax, total,\n    });\n    if (insertError) throw insertError;\n\n    const session = await stripe.checkout.sessions.create({\n      mode: \"payment\",\n      customer_email: customerEmail || undefined,\n      line_items: [\n        {\n          price_data: {\n            currency: \"eur\",\n            unit_amount: Math.round(total * 100),\n            product_data: {\n              name: `Pedido Xprint Wear #${orderNumber}`,\n              description: `${items.length} prenda(s) personalizada(s)`,\n            },\n          },\n          quantity: 1,\n        },\n      ],\n      metadata: { order_number: orderNumber },\n      success_url: `${origin}/thanks?order=${orderNumber}`,\n      cancel_url: `${origin}/checkout`,\n    });\n\n    await supabase\n      .from(\"orders\")\n      .update({ stripe_session_id: session.id })\n      .eq(\"order_number\", orderNumber);\n\n    return new Response(JSON.stringify({ url: session.url, orderNumber }), {\n      headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\n    });\n  } catch (err) {\n    console.error(err);\n    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : \"Error desconocido\" }), {\n      status: 500, headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\n    });\n  }\n});\n"
overwrite_file(
    "supabase/functions/create-checkout-session/index.ts",
    EDGE_FUNCTION,
    marker="invoice_data: invoiceData",
)

# --- 4. admin.tsx completo (muestra datos de factura) -----------------------
ADMIN_TSX = "import { createFileRoute, Link } from \"@tanstack/react-router\";\nimport { useEffect, useMemo, useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { Download, Package, TrendingUp, Clock, Truck, RefreshCw, FileText } from \"lucide-react\";\nimport { toast } from \"sonner\";\nimport { useAuth } from \"@/lib/auth-context\";\nimport { useIsAdmin } from \"@/lib/admin\";\nimport { supabase } from \"@/integrations/supabase/client\";\nimport type { CartItem } from \"@/lib/cart-store\";\n\nexport const Route = createFileRoute(\"/admin\")({\n  head: () => ({\n    meta: [\n      { title: \"Panel interno \u2014 Xprint Wear\" },\n      { name: \"robots\", content: \"noindex\" },\n    ],\n  }),\n  component: AdminPage,\n});\n\ntype OrderStatus = \"pending\" | \"paid\" | \"shipped\" | \"delivered\" | \"cancelled\";\n\n// Fila real de la tabla \"orders\" en Supabase.\ntype AdminOrder = {\n  id: string;\n  order_number: string;\n  status: OrderStatus;\n  stripe_payment_status: string | null;\n  customer_email: string | null;\n  customer_name: string | null;\n  customer_phone: string | null;\n  shipping_address: Record<string, unknown> | null;\n  invoice_data: { companyName?: string; taxId?: string; address?: string } | null;\n  items: CartItem[];\n  subtotal: number;\n  shipping: number;\n  tax: number;\n  total: number;\n  created_at: string;\n  paid_at: string | null;\n};\n\nconst STATUS_LABEL: Record<OrderStatus, string> = {\n  pending: \"Pendiente de pago\",\n  paid: \"Pagado \u00b7 por preparar\",\n  shipped: \"Enviado\",\n  delivered: \"Entregado\",\n  cancelled: \"Cancelado\",\n};\n\nconst STATUS_CLS: Record<OrderStatus, string> = {\n  pending: \"bg-amber-500/15 text-amber-700 dark:text-amber-300\",\n  paid: \"bg-sky-500/15 text-sky-700 dark:text-sky-300\",\n  shipped: \"bg-violet-500/15 text-violet-700 dark:text-violet-300\",\n  delivered: \"bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\",\n  cancelled: \"bg-red-500/15 text-red-700 dark:text-red-300\",\n};\n\nfunction csvCell(v: unknown) {\n  return `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n}\n\nfunction AdminPage() {\n  const { user, loading: authLoading } = useAuth();\n  const { isAdmin, checking } = useIsAdmin();\n\n  const [orders, setOrders] = useState<AdminOrder[] | null>(null);\n  const [loadingOrders, setLoadingOrders] = useState(false);\n  const [statusFilter, setStatusFilter] = useState<\"all\" | OrderStatus>(\"all\");\n  const [search, setSearch] = useState(\"\");\n  const [dateFrom, setDateFrom] = useState(\"\");\n  const [dateTo, setDateTo] = useState(\"\");\n  const [expandedId, setExpandedId] = useState<string | null>(null);\n\n  const loadOrders = async () => {\n    setLoadingOrders(true);\n    const { data, error } = await (supabase as any)\n      .from(\"orders\")\n      .select(\"*\")\n      .order(\"created_at\", { ascending: false });\n    setLoadingOrders(false);\n    if (error) {\n      toast.error(\"No se pudieron cargar los pedidos\");\n      console.error(error);\n      return;\n    }\n    setOrders((data ?? []) as AdminOrder[]);\n  };\n\n  useEffect(() => {\n    if (isAdmin) loadOrders();\n  }, [isAdmin]);\n\n  const filtered = useMemo(() => {\n    if (!orders) return [];\n    const q = search.trim().toLowerCase();\n    return orders.filter((o) => {\n      if (statusFilter !== \"all\" && o.status !== statusFilter) return false;\n      if (q) {\n        const hay =\n          o.order_number.toLowerCase().includes(q) ||\n          (o.customer_email ?? \"\").toLowerCase().includes(q) ||\n          (o.customer_name ?? \"\").toLowerCase().includes(q);\n        if (!hay) return false;\n      }\n      const created = o.created_at.slice(0, 10);\n      if (dateFrom && created < dateFrom) return false;\n      if (dateTo && created > dateTo) return false;\n      return true;\n    });\n  }, [orders, statusFilter, search, dateFrom, dateTo]);\n\n  const stats = useMemo(() => {\n    const revenue = filtered\n      .filter((o) => o.status !== \"pending\" && o.status !== \"cancelled\")\n      .reduce((s, o) => s + Number(o.total), 0);\n    const pendingPayment = filtered.filter((o) => o.status === \"pending\").length;\n    const toShip = filtered.filter((o) => o.status === \"paid\").length;\n    return { count: filtered.length, revenue, pendingPayment, toShip };\n  }, [filtered]);\n\n  const updateStatus = async (id: string, status: OrderStatus) => {\n    const { error } = await (supabase as any).from(\"orders\").update({ status }).eq(\"id\", id);\n    if (error) {\n      toast.error(\"No se pudo actualizar el estado\");\n      console.error(error);\n      return;\n    }\n    setOrders((prev) => (prev ? prev.map((o) => (o.id === id ? { ...o, status } : o)) : prev));\n    toast.success(\"Estado actualizado\");\n  };\n\n  const exportCsv = () => {\n    const headers = [\n      \"N\u00ba pedido\", \"Fecha\", \"Cliente\", \"Email\", \"Tel\u00e9fono\", \"Estado\",\n      \"Subtotal\", \"Env\u00edo\", \"Impuestos\", \"Total\",\n      \"Raz\u00f3n social\", \"CIF/NIF\", \"Direcci\u00f3n fiscal\",\n    ];\n    const rows = filtered.map((o) => [\n      o.order_number,\n      new Date(o.created_at).toLocaleString(\"es-ES\"),\n      o.customer_name ?? \"\",\n      o.customer_email ?? \"\",\n      o.customer_phone ?? \"\",\n      STATUS_LABEL[o.status],\n      Number(o.subtotal).toFixed(2),\n      Number(o.shipping).toFixed(2),\n      Number(o.tax).toFixed(2),\n      Number(o.total).toFixed(2),\n      o.invoice_data?.companyName ?? \"\",\n      o.invoice_data?.taxId ?? \"\",\n      o.invoice_data?.address ?? \"\",\n    ]);\n    const csv = [headers, ...rows].map((r) => r.map(csvCell).join(\",\")).join(\"\\n\");\n    const blob = new Blob([\"\\uFEFF\" + csv], { type: \"text/csv;charset=utf-8;\" });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\"a\");\n    a.href = url;\n    a.download = `pedidos_xprintwear_${new Date().toISOString().slice(0, 10)}.csv`;\n    a.click();\n    URL.revokeObjectURL(url);\n  };\n\n  // --- Estados de carga / acceso ---------------------------------------\n  if (authLoading || checking) {\n    return <main className=\"grid min-h-[60vh] place-items-center text-sm text-muted-foreground\">\u2026</main>;\n  }\n  if (!user) {\n    return (\n      <main className=\"mx-auto max-w-md px-6 py-24 text-center\">\n        <p className=\"font-display text-3xl uppercase\">Panel interno</p>\n        <p className=\"mt-3 text-sm text-muted-foreground\">Inicia sesi\u00f3n con tu cuenta de administradora.</p>\n        <Link\n          to=\"/auth\"\n          className=\"mt-8 inline-block rounded-full bg-foreground px-6 py-3 text-sm font-semibold uppercase tracking-widest text-background\"\n        >\n          Iniciar sesi\u00f3n\n        </Link>\n      </main>\n    );\n  }\n  if (!isAdmin) {\n    return (\n      <main className=\"mx-auto max-w-md px-6 py-24 text-center\">\n        <p className=\"font-display text-3xl uppercase\">Acceso restringido</p>\n        <p className=\"mt-3 text-sm text-muted-foreground\">\n          Esta cuenta ({user.email}) no tiene permisos de administradora.\n        </p>\n      </main>\n    );\n  }\n\n  // --- Panel --------------------------------------------------------\n  return (\n    <main className=\"mx-auto max-w-7xl px-4 pb-24 pt-10 sm:px-6\">\n      <div className=\"mb-6 flex flex-wrap items-end justify-between gap-3\">\n        <div>\n          <p className=\"text-xs uppercase tracking-[0.3em] text-muted-foreground\">Xprint Wear</p>\n          <h1 className=\"mt-1 font-display text-3xl uppercase leading-none tracking-tight sm:text-4xl\">\n            Panel de pedidos\n          </h1>\n        </div>\n        <div className=\"flex items-center gap-2\">\n          <button\n            onClick={loadOrders}\n            className=\"inline-flex items-center gap-1.5 rounded-full border border-border bg-background px-3 py-2 text-xs font-semibold uppercase tracking-wider transition hover:border-foreground\"\n          >\n            <RefreshCw className={`h-3.5 w-3.5 ${loadingOrders ? \"animate-spin\" : \"\"}`} /> Actualizar\n          </button>\n          <button\n            onClick={exportCsv}\n            disabled={filtered.length === 0}\n            className=\"holo-gradient inline-flex items-center gap-1.5 rounded-full px-4 py-2 text-xs font-semibold uppercase tracking-wider text-white disabled:cursor-not-allowed disabled:opacity-40\"\n          >\n            <Download className=\"h-3.5 w-3.5\" /> Exportar CSV\n          </button>\n        </div>\n      </div>\n\n      {/* Stats (sobre los pedidos filtrados) */}\n      <div className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-4\">\n        <Stat icon={<Package className=\"h-4 w-4\" />} label=\"Pedidos\" value={stats.count.toString()} />\n        <Stat icon={<TrendingUp className=\"h-4 w-4\" />} label=\"Facturaci\u00f3n\" value={`\u20ac${stats.revenue.toFixed(2)}`} />\n        <Stat icon={<Clock className=\"h-4 w-4\" />} label=\"Pendientes de pago\" value={stats.pendingPayment.toString()} />\n        <Stat icon={<Truck className=\"h-4 w-4\" />} label=\"Por enviar\" value={stats.toShip.toString()} />\n      </div>\n\n      {/* Filtros */}\n      <div className=\"mt-6 flex flex-wrap items-center gap-2 rounded-2xl border border-border bg-card p-3\">\n        <input\n          type=\"text\"\n          placeholder=\"Buscar por n\u00ba pedido, nombre o email\u2026\"\n          value={search}\n          onChange={(e) => setSearch(e.target.value)}\n          className=\"min-w-[220px] flex-1 rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-foreground\"\n        />\n        <select\n          value={statusFilter}\n          onChange={(e) => setStatusFilter(e.target.value as \"all\" | OrderStatus)}\n          className=\"rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-foreground\"\n        >\n          <option value=\"all\">Todos los estados</option>\n          {(Object.keys(STATUS_LABEL) as OrderStatus[]).map((s) => (\n            <option key={s} value={s}>{STATUS_LABEL[s]}</option>\n          ))}\n        </select>\n        <input\n          type=\"date\"\n          value={dateFrom}\n          onChange={(e) => setDateFrom(e.target.value)}\n          className=\"rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-foreground\"\n        />\n        <span className=\"text-xs text-muted-foreground\">a</span>\n        <input\n          type=\"date\"\n          value={dateTo}\n          onChange={(e) => setDateTo(e.target.value)}\n          className=\"rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-foreground\"\n        />\n      </div>\n\n      {/* Tabla de pedidos */}\n      <div className=\"mt-6 overflow-hidden rounded-2xl border border-border bg-card\">\n        {orders === null ? (\n          <p className=\"p-8 text-center text-sm text-muted-foreground\">Cargando pedidos\u2026</p>\n        ) : filtered.length === 0 ? (\n          <p className=\"p-8 text-center text-sm text-muted-foreground\">No hay pedidos con estos filtros.</p>\n        ) : (\n          <ul className=\"divide-y divide-border\">\n            {filtered.map((o) => (\n              <motion.li key={o.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>\n                <div\n                  onClick={() => setExpandedId((id) => (id === o.id ? null : o.id))}\n                  className=\"flex cursor-pointer flex-wrap items-center justify-between gap-3 px-5 py-4 transition hover:bg-muted/40\"\n                >\n                  <div className=\"flex min-w-[160px] items-center gap-3\">\n                    <div>\n                      <p className=\"font-display text-sm uppercase tracking-widest\">{o.order_number}</p>\n                      <p className=\"text-[11px] text-muted-foreground\">\n                        {new Date(o.created_at).toLocaleDateString(\"es-ES\", { day: \"numeric\", month: \"short\", year: \"numeric\" })}\n                      </p>\n                    </div>\n                  </div>\n                  <div className=\"min-w-[160px] flex-1\">\n                    <p className=\"truncate text-sm font-medium\">{o.customer_name || \"\u2014\"}</p>\n                    <p className=\"truncate text-[11px] text-muted-foreground\">{o.customer_email || \"\u2014\"}</p>\n                  </div>\n                  <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold uppercase tracking-widest ${STATUS_CLS[o.status]}`}>\n                    {STATUS_LABEL[o.status]}\n                  </span>\n                  {o.invoice_data && (\n                    <span\n                      title=\"Necesita factura\"\n                      className=\"inline-flex items-center gap-1 rounded-full bg-amber-500/15 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-widest text-amber-700 dark:text-amber-300\"\n                    >\n                      <FileText className=\"h-3 w-3\" /> Factura\n                    </span>\n                  )}\n                  <p className=\"w-24 text-right font-semibold\">\u20ac{Number(o.total).toFixed(2)}</p>\n                </div>\n\n                {expandedId === o.id && (\n                  <div className=\"border-t border-border bg-muted/20 px-5 py-4\" onClick={(e) => e.stopPropagation()}>\n                    <div className=\"mb-3 flex flex-wrap items-center gap-2\">\n                      <span className=\"text-xs uppercase tracking-widest text-muted-foreground\">Cambiar estado:</span>\n                      {(Object.keys(STATUS_LABEL) as OrderStatus[]).map((s) => (\n                        <button\n                          key={s}\n                          onClick={() => updateStatus(o.id, s)}\n                          className={`rounded-full border px-3 py-1 text-[11px] font-semibold uppercase tracking-wider transition ${\n                            o.status === s ? \"border-foreground bg-foreground text-background\" : \"border-border hover:border-foreground\"\n                          }`}\n                        >\n                          {STATUS_LABEL[s]}\n                        </button>\n                      ))}\n                    </div>\n\n                    {o.customer_phone && (\n                      <p className=\"mb-2 text-xs text-muted-foreground\">Tel\u00e9fono: {o.customer_phone}</p>\n                    )}\n                    {o.shipping_address && (\n                      <p className=\"mb-3 text-xs text-muted-foreground\">\n                        Env\u00edo: {Object.values(o.shipping_address).filter(Boolean).join(\", \")}\n                      </p>\n                    )}\n                    {o.invoice_data && (\n                      <div className=\"mb-3 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs\">\n                        <p className=\"mb-1 font-semibold uppercase tracking-wider text-amber-700 dark:text-amber-300\">\n                          Factura solicitada\n                        </p>\n                        {o.invoice_data.companyName && <p>Raz\u00f3n social: {o.invoice_data.companyName}</p>}\n                        {o.invoice_data.taxId && <p>CIF/NIF: {o.invoice_data.taxId}</p>}\n                        {o.invoice_data.address && <p>Direcci\u00f3n fiscal: {o.invoice_data.address}</p>}\n                      </div>\n                    )}\n\n                    <ul className=\"divide-y divide-border rounded-lg border border-border bg-card\">\n                      {o.items.map((i) => (\n                        <li key={i.id} className=\"flex items-center gap-3 px-3 py-2\">\n                          <div className=\"h-12 w-12 shrink-0 overflow-hidden rounded-md border border-border\" style={{ backgroundColor: \"#ffffff\" }}>\n                            {i.image && <img src={i.image} alt={i.name} className=\"h-full w-full object-contain mix-blend-multiply\" />}\n                          </div>\n                          <div className=\"min-w-0 flex-1\">\n                            <p className=\"truncate text-sm font-medium\">{i.name}</p>\n                            <p className=\"text-[11px] text-muted-foreground\">\n                              {i.size} \u00b7 {i.colorName} \u00b7 Cant. {i.qty}\n                              {i.elements.some((el) => el.kind === \"image\") ? \" \u00b7 logo\" : \"\"}\n                              {i.elements.some((el) => el.kind === \"text\" && el.text) ? \" \u00b7 texto\" : \"\"}\n                            </p>\n                          </div>\n                        </li>\n                      ))}\n                    </ul>\n\n                    <div className=\"mt-3 flex justify-end gap-6 text-xs text-muted-foreground\">\n                      <span>Subtotal: \u20ac{Number(o.subtotal).toFixed(2)}</span>\n                      <span>Env\u00edo: \u20ac{Number(o.shipping).toFixed(2)}</span>\n                      <span>Impuestos: \u20ac{Number(o.tax).toFixed(2)}</span>\n                      <span className=\"font-semibold text-foreground\">Total: \u20ac{Number(o.total).toFixed(2)}</span>\n                    </div>\n                  </div>\n                )}\n              </motion.li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </main>\n  );\n}\n\nfunction Stat({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {\n  return (\n    <div className=\"rounded-2xl border border-border bg-card p-5\">\n      <div className=\"flex items-center gap-1.5 text-[11px] uppercase tracking-widest text-muted-foreground\">\n        {icon} {label}\n      </div>\n      <p className=\"mt-2 font-display text-3xl leading-none\">{value}</p>\n    </div>\n  );\n}\n"
overwrite_file("src/routes/admin.tsx", ADMIN_TSX, marker="Factura solicitada")

print()
